import {parse,encode} from './converter.mjs';
const $=id=>document.getElementById(id);let track=null,readVersion=0;
function reset(){track=null;$('output').value='';$('copy').disabled=$('download').disabled=true;$('warnings').replaceChildren();draw(null);}
function message(text,error=false){$('status').textContent=text;$('status').classList.toggle('error',error);}
function draw(t){const canvas=$('preview'),ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);if(!t)return;const xs=[t.flags[0]],ys=[t.flags[1]];for(const l of t.lines){xs.push(l[0],l[2]);ys.push(l[1],l[3]);}const minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys),scale=Math.min(940/Math.max(1,maxX-minX),160/Math.max(1,maxY-minY));const x=v=>30+(v-minX)*scale,y=v=>30+(v-minY)*scale;ctx.lineWidth=1.5;for(const l of t.lines){ctx.strokeStyle=['#30332f','#866226','#667d91','#88877e','#a13d32','#a13d32'][l[4]];ctx.beginPath();ctx.moveTo(x(l[0]),y(l[1]));ctx.lineTo(x(l[2]),y(l[3]));ctx.stroke();}ctx.fillStyle='#48583c';ctx.fillRect(x(t.flags[0])-3,y(t.flags[1])-3,6,6);}
$('file').addEventListener('change',async()=>{const version=++readVersion;reset();const f=$('file').files[0];if(!f)return;if(f.size>10000000){message('Choose a file smaller than 10 MB.',true);return;}try{const text=await f.text();if(version!==readVersion)return;$('source').value=text;message(`Loaded ${f.name}. Select Convert track.`);}catch{message('Could not read the file. Choose it again.',true);}});
$('source').addEventListener('input',()=>{readVersion++;reset();message('Input changed. Convert again to refresh the code.');});$('lossy').addEventListener('change',()=>{reset();message('Compatibility option changed. Convert again.');});
$('form').addEventListener('submit',event=>{event.preventDefault();reset();try{track=parse($('source').value,{allowLossy:$('lossy').checked,decompress:s=>window.LZString.decompressFromBase64(s)});$('output').value=encode(track);for(const warning of track.warnings){const li=document.createElement('li');li.textContent=warning;$('warnings').append(li);}draw(track);$('copy').disabled=$('download').disabled=false;message(`${track.format}  /  ${track.lines.length.toLocaleString()} segments  /  ${$('output').value.length.toLocaleString()} characters. Ready to paste into Scratch.`);}catch(error){message(error.message,true);}});
$('copy').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('output').value);message('Copied. In Scratch, choose Track > Load track code and paste.');}catch{$('output').focus();$('output').select();message('Code selected. Press Ctrl+C or use your device / s Copy command.');}});
$('download').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([$ ('output').value],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='scratch-line-rider.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
$('clear').addEventListener('click',()=>{readVersion++;$('source').value='';$('file').value='';reset();message('Choose a file or paste a code to begin.');$('source').focus();});

